#!/usr/bin/env python3
"""Build the two 1600×1200 presentation boards from the exported vector source."""
import json, html, base64
from pathlib import Path
R=Path(__file__).resolve().parent
J=json.loads((R/'exports/components.json').read_text()); C=J['components']; W=J['width']; H=J['height']
COL=['#49c8ff','#fe82bd','#ffd271','#a9da69','#a59fff','#4fe0ca','#ff976f']
def paths(cs=C,dark=False,outline=False):
 return ''.join(f'<path d="{c["d"]}" fill="{"none" if outline else c["color_dark" if dark else "color_light"]}" fill-rule="evenodd" '+(f'stroke="{COL[i%7]}" stroke-width="2.6" ' if outline else '')+'/>' for i,c in enumerate(cs))
def svg(body,view=None,cls=''):
 return f'<svg class="{cls}" viewBox="{view or f"0 0 {W} {H}"}" xmlns="http://www.w3.org/2000/svg">{body}</svg>'
def mark(cs=C,dark=False): return svg(paths(cs,dark))
def crop(c):
 x,y,w,h=c['bbox']; pad=max(w,h)*.14
 return svg(paths([c]),f'{x-pad} {y-pad} {w+2*pad} {h+2*pad}')
def nodes(cs=C):
 out=''
 for c in cs:
  for h in c.get('handles',[]):
   a,b=h['anchor'],h['control']; out+=f'<path d="M {a[0]} {a[1]} L {b[0]} {b[1]}" stroke="#ff77cb" stroke-width="1.7"/><circle cx="{b[0]}" cy="{b[1]}" r="3.3" fill="#66f4ff"/>'
  for a in c.get('anchors',[]):
   if isinstance(a,dict): a=a.get('point',a.get('position',[0,0]))
   out+=f'<rect x="{a[0]-3}" y="{a[1]-3}" width="6" height="6" fill="#fff"/>'
 return out
CSS='''*{box-sizing:border-box}html,body{margin:0;width:1600px;height:1200px;overflow:hidden}body{font-family:Arial,Helvetica,sans-serif;background:#edf0f3;color:#252a2d;padding:32px 40px}header{height:118px;display:flex;justify-content:space-between;align-items:flex-start;border-bottom:2px solid #252a2d;margin-bottom:24px}.edition{font-size:12px;letter-spacing:2px;font-weight:700;margin-bottom:12px;color:#0043c2}h1{font-size:40px;letter-spacing:-1.4px;margin:0;font-weight:700;line-height:1.05}header p{font-size:14px;margin:12px 0;color:#52616e}.page-no{font-size:76px;font-weight:700;line-height:.85;letter-spacing:-5px;color:#0043c2}.meta{text-align:right;font:11px monospace;line-height:1.7;margin-top:12px}h2{font-size:19px;letter-spacing:-.4px;margin:0}h3{font-size:14px;margin:0}p{margin:0}svg{display:block;width:100%;height:100%}.panel{background:#fff;overflow:hidden}.bar{height:49px;display:flex;align-items:center;justify-content:space-between;padding:0 20px;border-bottom:1px solid #cfd5dd}.bar span{font:11px monospace;color:#52616e}.blue{background:#102b50;color:#fff}.blue .bar{border-color:#315071}.blue .bar span{color:#bdd2ec}.blueprint{background-image:linear-gradient(#ffffff09 1px,transparent 1px),linear-gradient(90deg,#ffffff09 1px,transparent 1px),linear-gradient(#ffffff0c 1px,transparent 1px),linear-gradient(90deg,#ffffff0c 1px,transparent 1px);background-size:16px 16px,16px 16px,80px 80px,80px 80px}.caption{font-size:12px;color:#52616e;line-height:1.5}.mono{font-family:monospace}.footer{display:flex;justify-content:space-between;align-items:center;border-top:1px solid #aab5bf;height:40px;font:11px monospace;color:#52616e;margin-top:16px}.top1{height:485px;display:grid;grid-template-columns:830px 1fr;gap:20px}.outline{height:335px;padding:14px 15px 0}.legend{display:flex;gap:24px;padding:16px 24px;font-size:12px}.legend strong{color:#ff8cce}.metrics{display:flex;justify-content:space-between;margin:0 24px;padding-top:14px;border-top:1px solid #315071;font:12px monospace;color:#c3dbf4}.right1{display:grid;grid-template-columns:1fr 272px;height:485px;background:white}.masters{display:flex;flex-direction:column}.master{height:242px;padding:24px 14px 18px;display:flex;flex-direction:column}.master svg{height:164px}.master p{font:10px monospace;line-height:1.6}.master.dark{background:#252a2d;color:#fff}.layers{background:#303236;color:#eff0f3;padding:0 12px}.layers-title{height:43px;display:flex;align-items:center;justify-content:space-between;font-size:12px;border-bottom:1px solid #555}.layer{height:24px;display:flex;align-items:center;gap:6px;border-bottom:1px solid #ffffff0c;font:9px monospace;white-space:nowrap}.eye{font-size:12px;color:#c5ccd4}.swatch{height:7px;width:7px;flex-shrink:0}.layer-name{flex:1}.layer-count{color:#c6cdd6}.library-title{display:flex;justify-content:space-between;align-items:center;height:60px}.library-title p{font-size:12px;color:#52616e}.library{display:grid;grid-template-columns:repeat(9,1fr);gap:10px;height:365px}.piece{height:176px;background:#fff;padding:10px 10px 8px;display:flex;flex-direction:column;border-top:2px solid #0043c2}.piece-head{display:flex;justify-content:space-between;font:10px monospace;color:#52616e}.piece-head b{font-size:14px;color:#0043c2}.piece-art{height:100px;padding:6px 17px}.piece-id{font:9px monospace;line-height:1.4;overflow-wrap:anywhere;min-height:25px}.piece-info{font:9px monospace;color:#52616e;margin-top:auto}.summary{background:#0043c2;color:white;padding:16px;font-size:15px;line-height:1.4}.summary b{font-size:37px;display:block;letter-spacing:-1px}.summary small{font-size:11px;line-height:1.5;display:block;margin-top:8px}.top2{display:grid;grid-template-columns:720px 1fr;gap:20px;height:430px}.explode{height:340px;position:relative;overflow:hidden}.explode-note{font:11px monospace;padding:0 20px;color:#c3dbf4}.macro{padding:12px 18px}.macro-head{display:grid;grid-template-columns:110px 1fr 1fr;gap:10px;font:10px monospace;color:#52616e;margin-bottom:7px}.macro-row{display:grid;grid-template-columns:110px 1fr 1fr;gap:10px;height:104px;margin-bottom:8px}.zone{display:flex;justify-content:center;flex-direction:column;font-size:13px;line-height:1.4}.zone b{font:11px monospace;color:#0043c2;margin-bottom:6px}.macro-art{background:#f0f3f6;overflow:hidden;border:1px solid #d3dae0}.apps-title{height:58px;display:flex;align-items:center;justify-content:space-between}.apps-title p{font-size:12px;color:#52616e}.apps{display:grid;grid-template-columns:1.25fr 1fr 1fr 1fr;gap:14px;height:333px}.app{background:#fff;overflow:hidden;display:flex;flex-direction:column}.scene{height:254px;background:#dce3e9}.app-copy{padding:12px 14px}.app-copy h3{font-size:13px;margin-bottom:6px}.app-copy p{font:10px monospace;color:#52616e;line-height:1.5}.manifest{height:115px;display:grid;grid-template-columns:220px repeat(6,1fr);background:#252a2d;color:#fff;margin-top:20px}.manifest-intro{padding:20px}.manifest-intro h2{font-size:18px;line-height:1.2}.manifest-intro p{font:10px monospace;color:#bac6d1;margin-top:8px}.format{padding:22px 13px;border-left:1px solid #ffffff25}.format strong{font-size:23px;display:block;margin-bottom:10px}.format p{font:10px monospace;color:#c5ced9;line-height:1.4}'''
CSS+=''' .board2 .top2{height:380px}.board2 .explode{height:286px}.board2 .macro-row{height:88px}.board2 .apps-title{height:50px}.board2 .apps{height:275px}.board2 .scene{height:204px}.board2 .manifest{height:96px;margin-top:16px}.board2 .format{padding:16px 13px}.board2 .format strong{margin-bottom:6px}.board2 .manifest-intro{padding:16px 20px}.board2 .footer{height:32px;margin-top:14px}'''
def header(n,title,sub):return f'<header><div><div class="edition">KESWA ELECTRICAL / VECTOR ASSET LIBRARY</div><h1>{title}</h1><p>{sub}</p></div><div><div class="page-no">{n}</div><div class="meta">CONTEST #2800912<br>ENGINEERED FOR REUSE</div></div></header>'
def footer(n):return f'<footer class="footer"><span>KESWA ELECTRICAL · 17 COMPONENTS · OUTLINED WORDMARK</span><span>VECTOR ENGINEERING / SHEET {n} OF 02</span></footer>'
def write(name,body): (R/name).write_text('<!doctype html><html lang="en"><meta charset="utf-8"><meta name="viewport" content="width=1600"><title>KESWA · Vector engineering</title><style>'+CSS+'</style><body class="'+('board2' if 'board2' in name else 'board1')+'">'+body+'</body></html>')
count=sum(c['nodes'] for c in C)
board=header('01','Every element. Independently editable.','Cubic Bézier contours, precise straight segments and a named, reusable 17-piece library.')
board+='<div class="top1"><section class="panel blue"><div class="bar"><h2>Adobe Illustrator Ctrl+Y · Outline blueprint</h2><span>VECTOR NODE PREVIEW</span></div><div class="outline blueprint">'+svg(paths(outline=True)+nodes(),f'100 120 {W-150} 520')+'</div><div class="legend"><span>■ Anchor point</span><span><strong>●—</strong> Cubic tangent handle</span><span>Layer-coded contours</span></div><div class="metrics"><span>17 NAMED COMPONENTS</span><span>'+str(count)+' ANCHORS</span><span>0 LIVE TYPE IN LOGO</span></div></section><section class="right1"><div class="masters"><div class="master"><h3>Light master</h3>'+mark()+'<p>CHARCOAL #252A2D<br>COBALT #0043C2</p></div><div class="master dark"><h3>Reversed master</h3>'+mark(dark=True)+'<p>WHITE #FFFFFF<br>ELECTRIC BLUE #0052FF</p></div></div><div class="layers"><div class="layers-title"><b>Layers</b><span>17 objects ▤</span></div>'
for i,c in enumerate(C):board+=f'<div class="layer"><span class="eye">◉</span><span class="swatch" style="background:{COL[i%7]}"></span><span class="layer-name">{c["id"]}</span><span class="layer-count">{c["nodes"]}</span></div>'
board+='</div></section></div><div class="library-title"><h2>17 individually selectable components</h2><p>Separate artboards · named paths · original-scale bounds in px</p></div><section class="library">'
for c in C:
 x,y,w,h=c['bbox'];board+=f'<article class="piece"><div class="piece-head"><b>{c["id"][:2]}</b><span>{c["nodes"]} anchors</span></div><div class="piece-art">{crop(c)}</div><div class="piece-id">{c["id"]}</div><div class="piece-info">{w:.1f} × {h:.1f} px</div></article>'
board+='<article class="piece summary"><b>17 / 17</b>Ready to select.<small>Logo lettering is geometry.<br>No font installation required.</small></article></section>'+footer('01')
write('board1-codex.html',board)
# Floating architecture: every object has its own offset and connector.
ex='<defs><pattern id="grid" width="35" height="35" patternUnits="userSpaceOnUse"><path d="M35 0H0V35" fill="none" stroke="#93b7dc" stroke-opacity=".17"/></pattern></defs><rect width="720" height="340" fill="url(#grid)"/>'
ex+='<g transform="translate(20 170) matrix(.30 .07 -.19 .21 0 0)"><rect x="100" y="100" width="2050" height="520" fill="#c7d7eb" fill-opacity=".12" stroke="#7396be" stroke-width="3"/>'+paths(outline=True)+'</g>'
for i,c in enumerate(C):
 shift=68 if i<7 else 25
 ex+=f'<g transform="translate(20 {170-shift-(i%3)*12}) matrix(.30 .07 -.19 .21 0 0)"><path d="{c["d"]}" fill="{COL[i%7]}" fill-rule="evenodd"/></g>'
 x,y,w,h=c['bbox']; px=20+.30*(x+w/2)-.19*(y+h/2); py=170+.07*(x+w/2)+.21*(y+h/2)
 ex+=f'<path d="M{px:.1f} {py:.1f}v{-shift-(i%3)*12}" stroke="#bdd6f3" stroke-dasharray="3 4" opacity=".65"/><text x="{px:.1f}" y="{py-shift-(i%3)*12-8:.1f}" fill="white" font-family="monospace" font-size="10">{i+1:02}</text>'
board=header('02','One source. Countless applications.','Independent geometry for brand layouts, fabrication workflows and scalable production artwork.')
board+='<div class="top2"><section class="panel blue"><div class="bar"><h2>Exploded layer architecture</h2><span>17 INDEPENDENT PIECES</span></div><div class="explode">'+svg(ex,'0 0 720 340')+'</div><p class="explode-note">Independent offsets reveal the original assembly beneath.</p></section><section class="panel"><div class="bar"><h2>1000% edge inspection</h2><span>SAME SOURCE COORDINATES</span></div><div class="macro"><div class="macro-head"><span>CRITICAL ZONE</span><span>ORIGINAL AI RASTER</span><span>CUBIC BÉZIER VECTOR</span></div>'
# Each window is 22 source pixels wide, rendered to ~230 display pixels.
zones=[('01','S · inner curve',977,245),('02','K · chevron gap',397,302),('03','A · apex / delta',1848,322)]
for num,title,x,y in zones:
 view=f'{x} {y} 30.5 8.6'
 raster=f'<image href="assets/source-light.png" width="{W}" height="{H}"/>'
 vector_art=svg(paths(),view); raster_art=svg(raster,view)
 if num=='03':
  pair=['1840 320 15.25 8.6','1899 177 15.25 8.6']
  vector_art='<div style="display:flex;height:100%">'+''.join('<div style="width:50%;height:100%">'+svg(paths(),v)+'</div>' for v in pair)+'</div>'
  raster_art='<div style="display:flex;height:100%">'+''.join('<div style="width:50%;height:100%">'+svg(raster,v)+'</div>' for v in pair)+'</div>'
 board+=f'<div class="macro-row"><div class="zone"><b>ZONE {num}</b>{title}</div><div class="macro-art">{raster_art}</div><div class="macro-art">{vector_art}</div></div>'
board+='</div></section></div><div class="apps-title"><h2>Industrial identity, assembled from the same pieces</h2><p>Application studies · vector placement mockups</p></div><div class="apps">'
def lock(x,y,w,h,cs=C,dark=False):return f'<svg x="{x}" y="{y}" width="{w}" height="{h}" viewBox="0 0 {W} {H}">{paths(cs,dark)}</svg>'
# Deliberately technical, clean elevations rather than photorealism claims.
van='<defs><linearGradient id="van" x2="0" y2="1"><stop stop-color="#fff"/><stop offset="1" stop-color="#c4ced8"/></linearGradient></defs><rect width="480" height="300" fill="#dce4eb"/><path d="M0 252H480" stroke="#a6b6c4"/><ellipse cx="247" cy="251" rx="205" ry="13" fill="#aebbc8"/><path d="M32 101Q32 83 52 83H323L382 137H427Q444 137 448 160L455 224H33Z" fill="url(#van)" stroke="#8e9ca9" stroke-width="2"/><path d="M328 93L374 139H328Z" fill="#243d51"/><path d="M286 93H316V139H286Z" fill="#243d51"/><path d="M278 85V218M319 145V218M40 201H449" stroke="#96a5b3"/><rect x="326" y="152" width="17" height="4" rx="2" fill="#5b6a78"/><path d="M40 194H261L303 220H40Z" fill="#0043c2"/><svg x="208" y="111" width="64" height="74" viewBox="'+ ' '.join(str(v) for v in C[6]['bbox']) +'">'+paths([C[6]])+'</svg>'+lock(40,108,193,66)+'<circle cx="110" cy="226" r="35" fill="#222c35"/><circle cx="110" cy="226" r="18" fill="#a8b5c0"/><circle cx="110" cy="226" r="8" fill="#596b7a"/><circle cx="380" cy="226" r="35" fill="#222c35"/><circle cx="380" cy="226" r="18" fill="#a8b5c0"/><circle cx="380" cy="226" r="8" fill="#596b7a"/>'
plate='<defs><linearGradient id="steel"><stop stop-color="#abb8c2"/><stop offset=".45" stop-color="#e4e9ed"/><stop offset="1" stop-color="#9cabb8"/></linearGradient></defs><rect width="380" height="300" fill="#24313d"/><path d="M20 0V300M360 0V300" stroke="#50606d"/><rect x="35" y="72" width="310" height="153" rx="4" fill="url(#steel)" stroke="#f4f6f7"/>'+''.join(f'<circle cx="{x}" cy="{y}" r="5" fill="#596a78"/><path d="M{x-3} {y+2}l6 -4" stroke="#d9e1e7"/>' for x in [48,332] for y in [85,212])+lock(63,86,252,89)+'<path d="M65 179H315" stroke="#7d8f9d"/><text x="190" y="197" fill="#344553" text-anchor="middle" font-size="10" font-family="monospace">MAIN SWITCHBOARD / 400 V</text>'
wear='<rect width="380" height="300" fill="#cfd8df"/><path d="M116 29L66 55L25 120L83 151L100 119V298H282V119L298 151L355 120L314 55L263 29L235 15H144Z" fill="#e5ed48" stroke="#b4ba39"/><path d="M144 17Q189 68 236 17L217 65H161Z" fill="#2d3c45"/><path d="M116 29L102 298M263 29L279 298" stroke="#c4ce38" stroke-width="3"/><path d="M96 205H284V235H96Z" fill="#e5e9e8"/><path d="M96 211H284M96 229H284" stroke="#99a6ab"/>'+lock(187,88,90,42)+'<path d="M187 130H275" stroke="#bdc337"/><path d="M173 64V190" stroke="#b5bd32"/>'
badges='<rect width="380" height="300" fill="#e2e8ed"/><rect x="32" y="31" width="316" height="72" fill="#fff"/>'+lock(52,34,276,65)+'<rect x="32" y="122" width="142" height="147" rx="4" fill="#0043c2"/><svg x="39" y="135" width="128" height="104" viewBox="140 150 1950 330">'+paths([C[0],C[1],C[6]],True)+'</svg><text x="103" y="249" text-anchor="middle" fill="white" font-size="10" font-family="monospace">01 + 02 + 07</text><circle cx="270" cy="196" r="75" fill="#252a2d"/><circle cx="270" cy="196" r="67" fill="none" stroke="#7f8a95"/>'+lock(207,157,126,66,dark=True)+'<text x="270" y="234" text-anchor="middle" fill="#d3dde5" font-size="9" font-family="monospace">ELECTRICAL SERVICES</text>'
for scene,title,desc,v in [(van,'Commercial service van','Wordmark + 07 delta motif','0 0 480 300'),(plate,'CNC / laser nameplate','DXF path placement · aluminum study','0 0 380 300'),(wear,'High-visibility workwear','Chest embroidery placement study','0 0 380 300'),(badges,'Modular brand marks','Icon · horizontal banner · stacked badge','0 0 380 300')]:
 board+=f'<article class="app"><div class="scene">{svg(scene,v)}</div><div class="app-copy"><h3>{title}</h3><p>{desc}</p></div></article>'
board+='</div><section class="manifest"><div class="manifest-intro"><h2>Six-format<br>delivery manifest</h2><p>Master + isolated assets</p></div>'
for fmt,desc in [('AI','Illustrator interchange<br>CC import not yet verified'),('SVG','Semantic layer groups<br>17 isolated pieces'),('EPS','PostScript paths<br>Named group comments'),('DXF','17 named CAD layers<br>Lines + curve entities'),('PDF','3 vector proof pages<br>Light / dark / blueprint'),('PNG','3840 px transparency<br>Individual raster exports')]:board+=f'<div class="format"><strong>.{fmt}</strong><p>{desc}</p></div>'
board+='</section>'+footer('02')
write('board2-codex.html',board)
print('Built board1-codex.html and board2-codex.html from',len(C),'components')
